insert into public.rules (id, version, category, verification_status, enabled, definition) values
('FED-EMTALA-001', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-EMTALA-001","name":"EMTALA: no payment-related delay of screening or stabilization","description":"A hospital may not delay a medical screening examination or necessary stabilizing treatment to inquire about payment method or insurance status. Registration may proceed only in a way that does not delay screening or treatment.","category":"federal_law","payerScope":"All payers, including self-pay","planScope":"All","coverageTypes":"any","settings":["emergency"],"effectiveDate":"1986-04-07","jurisdiction":"US-Federal","source":"42 U.S.C. § 1395dd; 42 CFR § 489.24(d)(4)","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-G/part-489/subpart-B/section-489.24","verificationStatus":"reference_cited","requiredInputs":["visit.setting","visit.edPhase"],"logicSummary":"If the visit is an ED visit and the patient has not completed screening and any needed stabilization, stop: return ED workflow, no collection, no financial-prerequisite language. Unknown phase is treated as pre-screening.","logicKey":"ed_emtala_gate","priority":1,"conflictBehavior":"blocking","reviewer":"Compliance / ED Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-MSP-001', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MSP-001","name":"MSP: working aged — employer group plan primary (20+ employees)","description":"For a beneficiary entitled to Medicare by age who has group health plan coverage through their own or a spouse''s current employment with an employer of 20 or more employees, the group health plan pays first and Medicare is secondary.","category":"federal_law","payerScope":"Original Medicare","planScope":"Employer group health plan + Medicare","coverageTypes":["medicare_original","commercial_employer"],"settings":"any","effectiveDate":"1983-01-01","jurisdiction":"US-Federal","source":"42 U.S.C. § 1395y(b)(1)(A); 42 CFR Part 411 Subpart E (§ 411.172); CMS Pub. 100-05 (MSP Manual) Ch. 1–2","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-B/part-411/subpart-E","verificationStatus":"reference_cited","requiredInputs":["msp.entitlementBasis","msp.currentEmployment","msp.employerSize"],"logicSummary":"Age basis + current-employment GHP + employer size ≥ 20 → GHP primary. Age basis + no current employment (e.g., retiree plan) → Medicare primary. Any unknown → supervisor review.","logicKey":"msp_order","priority":10,"conflictBehavior":"blocking","reviewer":"Compliance / MSP coordinator","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-MSP-002', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MSP-002","name":"MSP: disability — large group health plan primary (100+ employees)","description":"For a beneficiary under 65 entitled to Medicare by disability who has large group health plan coverage based on current employment (employer of 100 or more employees), the large group health plan pays first.","category":"federal_law","payerScope":"Original Medicare","planScope":"Large group health plan + Medicare","coverageTypes":["medicare_original","commercial_employer"],"settings":"any","effectiveDate":"1987-01-01","jurisdiction":"US-Federal","source":"42 U.S.C. § 1395y(b)(1)(B); 42 CFR Part 411 Subpart H; CMS Pub. 100-05 Ch. 1–2","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-B/part-411/subpart-H","verificationStatus":"reference_cited","requiredInputs":["msp.entitlementBasis","msp.currentEmployment","msp.employerSize"],"logicSummary":"Disability basis + current-employment LGHP + employer size ≥ 100 → LGHP primary; otherwise Medicare primary; unknowns → review.","logicKey":"msp_order","priority":10,"conflictBehavior":"blocking","reviewer":"Compliance / MSP coordinator","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-MSP-003', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MSP-003","name":"MSP: ESRD 30-month coordination period","description":"For a beneficiary entitled to Medicare based on ESRD, a group health plan pays first during the 30-month coordination period, regardless of employer size or employment status.","category":"federal_law","payerScope":"Original Medicare","planScope":"Group health plan + Medicare (ESRD)","coverageTypes":["medicare_original","commercial_employer"],"settings":"any","effectiveDate":"1997-08-05","jurisdiction":"US-Federal","source":"42 U.S.C. § 1395y(b)(1)(C); 42 CFR § 411.162; CMS Pub. 100-05 Ch. 2","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-B/part-411/subpart-F","verificationStatus":"reference_cited","requiredInputs":["msp.entitlementBasis","msp.esrdInCoordinationPeriod"],"logicSummary":"ESRD basis + inside coordination period → GHP primary; after the period → Medicare primary; unknown → review.","logicKey":"msp_order","priority":10,"conflictBehavior":"blocking","reviewer":"Compliance / MSP coordinator","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-MSP-004', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MSP-004","name":"MSP: hospital must determine payer order before billing Medicare","description":"Hospitals must determine whether Medicare is primary for each inpatient and outpatient encounter (commonly via the MSP questionnaire). Card order, patient preference, or the higher copay never sets payer order.","category":"federal_law","payerScope":"Original Medicare","planScope":"Medicare with any other coverage","coverageTypes":["medicare_original"],"settings":"any","effectiveDate":"1983-01-01","jurisdiction":"US-Federal","source":"42 CFR § 489.20(g); CMS Pub. 100-05 (MSP Manual) Ch. 3 § 20","sourceUrl":"https://www.cms.gov/regulations-and-guidance/guidance/manuals/internet-only-manuals-ioms-items/cms019017","verificationStatus":"reference_cited","requiredInputs":["msp.questionnaireCompleted"],"logicSummary":"Original Medicare + another non-supplement, non-Medicaid plan + MSP questionnaire not completed → verification required.","logicKey":"msp_questionnaire","priority":9,"conflictBehavior":"blocking","reviewer":"Compliance / MSP coordinator","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-MCD-001', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MCD-001","name":"Medicaid is payer of last resort","description":"Medicaid generally pays only after all other liable third parties, including Medicare and commercial coverage. A Medicaid plan ordered ahead of other active coverage is a coordination conflict.","category":"federal_law","payerScope":"Medicaid / Medicaid managed care","planScope":"Medicaid with any other coverage","coverageTypes":["medicaid","medicaid_managed_care"],"settings":"any","effectiveDate":"1965-07-30","jurisdiction":"US-Federal","source":"42 U.S.C. § 1396a(a)(25); 42 CFR § 433.139","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-C/part-433/subpart-D/section-433.139","verificationStatus":"reference_cited","requiredInputs":["plans[].type","plans[].payerOrder"],"logicSummary":"If Medicaid is not last among active plans → supervisor review (coordination conflict). If Medicaid is secondary/tertiary → do not collect at registration; wait for adjudication.","logicKey":"medicaid_last_resort","priority":11,"conflictBehavior":"blocking","reviewer":"Compliance / Medicaid billing","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-MCD-002', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MCD-002","name":"QMB: no billing of Medicare cost-sharing","description":"Providers may not bill Qualified Medicare Beneficiaries for Medicare deductibles, coinsurance, or copayments, regardless of whether Medicaid pays.","category":"federal_law","payerScope":"Medicare + Medicaid (QMB)","planScope":"Dual-eligible, QMB","coverageTypes":["medicare_original","medicare_advantage","medicaid","medicaid_managed_care"],"settings":"any","effectiveDate":"1997-08-05","jurisdiction":"US-Federal","source":"42 U.S.C. § 1396a(n)(3)(B); 42 U.S.C. § 1395cc(a)(1)(A); CMS MLN Booklet ''Prohibition on Billing Dually Eligible Individuals Enrolled in the QMB Program''","sourceUrl":"https://www.cms.gov/outreach-and-education/medicare-learning-network-mln/mlnproducts/downloads/qmb.pdf","verificationStatus":"reference_cited","requiredInputs":["plans[].qmb"],"logicSummary":"Any active Medicaid plan flagged QMB → no collection of Medicare cost-sharing. Terminal.","logicKey":"qmb_protection","priority":5,"conflictBehavior":"blocking","reviewer":"Compliance","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-MCD-003', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MCD-003","name":"Medicaid cost-sharing limits and exemptions","description":"Federal rules cap Medicaid cost-sharing and exempt certain groups and services (for example, many children, pregnancy-related services, emergency services). Actual amounts are set by each state and must come from a verified state rule.","category":"federal_law","payerScope":"Medicaid / Medicaid managed care","planScope":"Medicaid as sole or primary payer","coverageTypes":["medicaid","medicaid_managed_care"],"settings":"any","effectiveDate":"2013-07-15","jurisdiction":"US-Federal","source":"42 CFR §§ 447.50–447.57","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-C/part-447/subpart-A","verificationStatus":"reference_cited","requiredInputs":["plans[].costSharingExempt","state Medicaid cost-sharing rule"],"logicSummary":"Exempt → no collection. Exemption unknown → verify. Not exempt → collect only a verified copay AND only if the state cost-sharing rule for the jurisdiction is marked verified; otherwise verification required.","logicKey":"medicaid_cost_sharing","priority":12,"conflictBehavior":"blocking","reviewer":"Compliance / Medicaid billing","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-NSA-001', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-NSA-001","name":"No Surprises Act: out-of-network emergency cost-sharing","description":"For emergency services from an out-of-network facility, group and individual health plans must apply in-network cost-sharing and the patient may not be balance billed. Out-of-network ED cost-sharing must be reviewed rather than collected at the desk.","category":"federal_law","payerScope":"Group & individual health plans","planScope":"Commercial, marketplace","coverageTypes":["commercial_employer","commercial_individual","marketplace"],"settings":["emergency"],"effectiveDate":"2022-01-01","jurisdiction":"US-Federal","source":"42 U.S.C. § 300gg-111; 45 CFR § 149.110","sourceUrl":"https://www.ecfr.gov/current/title-45/subtitle-A/subchapter-B/part-149/subpart-B/section-149.110","verificationStatus":"reference_cited","requiredInputs":["visit.networkStatus","visit.setting"],"logicSummary":"ED + out-of-network + commercial/marketplace plan → no desk collection; refer for billing review.","logicKey":"nsa_oon_emergency","priority":13,"conflictBehavior":"blocking","reviewer":"Compliance / Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-MEDIGAP-001', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MEDIGAP-001","name":"Medigap supplements Original Medicare only","description":"A Medicare Supplement (Medigap) policy pays after Original Medicare. It does not pay Medicare Advantage cost-sharing and cannot be primary.","category":"federal_law","payerScope":"Medigap","planScope":"Standardized Medigap plans","coverageTypes":["medigap"],"settings":"any","effectiveDate":"1992-07-30","jurisdiction":"US-Federal","source":"Social Security Act § 1882 (42 U.S.C. § 1395ss); CMS ''Choosing a Medigap Policy'' (Pub. 02110)","sourceUrl":"https://www.medicare.gov/publications/02110-medigap-guide-health-insurance.pdf","verificationStatus":"reference_cited","requiredInputs":["plans[].type","plans[].payerOrder"],"logicSummary":"Medigap without active Original Medicare, Medigap with Medicare Advantage, or Medigap ordered first → supervisor review.","logicKey":"medigap_structure","priority":11,"conflictBehavior":"blocking","reviewer":"Compliance","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-MEDICARE-001', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MEDICARE-001","name":"Original Medicare cost-sharing is deductible + coinsurance on the approved amount","description":"Original Medicare cost-sharing generally consists of the Part A or Part B deductible plus coinsurance calculated on the Medicare-approved amount, not a fixed office-visit copay. Current-year amounts must be entered from a verified source.","category":"federal_law","payerScope":"Original Medicare","planScope":"Parts A & B","coverageTypes":["medicare_original"],"settings":"any","effectiveDate":"1966-07-01","jurisdiction":"US-Federal","source":"42 CFR §§ 409.82–409.83 (Part A), 410.152 and 410.160 (Part B)","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-B/part-410/subpart-E","verificationStatus":"reference_cited","requiredInputs":["benefits.deductibleRemainingCents","benefits.coinsuranceBp","visit.allowedAmountEstimateCents"],"logicSummary":"Never treat Medicare as a fixed-copay plan. Produce an estimate only from verified remaining deductible + coinsurance + facility allowed-amount estimate, and only when the facility estimate policy allows.","logicKey":"medicare_original_cost_sharing","priority":20,"conflictBehavior":"blocking","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FED-TRICARE-001', 1, 'federal_law', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-TRICARE-001","name":"TRICARE generally pays after other health insurance","description":"TRICARE is generally secondary to other health insurance, with statutory exceptions (e.g., Medicaid and certain TRICARE supplements). TRICARE ordered ahead of other health insurance needs review.","category":"federal_law","payerScope":"TRICARE","planScope":"All TRICARE programs","coverageTypes":["tricare"],"settings":"any","effectiveDate":"1986-01-01","jurisdiction":"US-Federal","source":"10 U.S.C. § 1079(j); 32 CFR § 199.8","sourceUrl":"https://www.ecfr.gov/current/title-32/subtitle-A/chapter-I/subchapter-M/part-199/section-199.8","verificationStatus":"reference_cited","requiredInputs":["plans[].type","plans[].payerOrder"],"logicSummary":"TRICARE ordered before an active commercial/employer plan → supervisor review.","logicKey":"tricare_order","priority":11,"conflictBehavior":"blocking","reviewer":"Compliance","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('STATE-NC-MCD-001', 1, 'state_law', 'draft', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"STATE-NC-MCD-001","name":"NC Medicaid cost-sharing schedule","description":"Placeholder for North Carolina Medicaid copay amounts, exemptions, and point-of-service collection rules. Must be completed from current NC DHHS / NC Medicaid guidance before Ledgr may recommend any Medicaid copay for NC encounters.","category":"state_law","payerScope":"NC Medicaid (FFS and Prepaid Health Plans)","planScope":"NC Medicaid","coverageTypes":["medicaid","medicaid_managed_care"],"settings":"any","effectiveDate":"2026-01-01","jurisdiction":"NC","source":"NC Medicaid clinical/billing policy — TO BE SUPPLIED by compliance","verificationStatus":"draft","requiredInputs":["visit.jurisdiction"],"logicSummary":"While this rule is draft, no Medicaid copay may be recommended for NC; returns verification required.","logicKey":"state_medicaid_schedule","priority":12,"conflictBehavior":"blocking","reviewer":"Compliance (NC)","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('PLAN-MEDIGAP-G', 1, 'plan_benefit', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"PLAN-MEDIGAP-G","name":"Medigap Plan G benefit structure","description":"Plan G covers Medicare Part A and Part B cost-sharing covered by the standardized plan, including the Part A deductible and Part B coinsurance, but generally does NOT cover the Part B deductible.","category":"plan_benefit","payerScope":"Medigap","planScope":"Standardized Plan G","coverageTypes":["medigap"],"settings":"any","effectiveDate":"2010-06-01","jurisdiction":"US-Federal (standardized)","source":"CMS ''Choosing a Medigap Policy'' (Pub. 02110), Medigap plan chart","sourceUrl":"https://www.medicare.gov/publications/02110-medigap-guide-health-insurance.pdf","verificationStatus":"reference_cited","requiredInputs":["plans[].medigapLetter","medicare.benefits.deductibleRemainingCents"],"logicSummary":"Original Medicare + active Plan G: no standard copay. Inpatient → no facility collection. Outpatient: Part B deductible verified met → no collection; deductible remaining → at most the remaining Part B deductible, as an estimate only and only if the facility allows estimates; unknown → verification required.","logicKey":"medigap_g","priority":30,"conflictBehavior":"blocking","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('PLAN-MEDIGAP-OTHER', 1, 'plan_benefit', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"PLAN-MEDIGAP-OTHER","name":"Other Medigap letters require plan-specific benefit verification","description":"Medigap letters differ (some cover the Part B deductible on older policies; some have copays). Ledgr does not assume benefits for letters other than G.","category":"plan_benefit","payerScope":"Medigap","planScope":"Plans A, B, C, D, F, K, L, M, N (and high-deductible variants)","coverageTypes":["medigap"],"settings":"any","effectiveDate":"2010-06-01","jurisdiction":"US-Federal (standardized)","source":"CMS ''Choosing a Medigap Policy'' (Pub. 02110)","verificationStatus":"reference_cited","requiredInputs":["plans[].medigapLetter"],"logicSummary":"Medigap letter other than G, or missing letter → verification required.","logicKey":"medigap_other","priority":30,"conflictBehavior":"blocking","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('PLAN-MA-001', 1, 'plan_benefit', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"PLAN-MA-001","name":"Medicare Advantage uses plan-specific benefits","description":"Medicare Advantage plans set their own copays, coinsurance, networks, and authorization rules. Original Medicare cost-sharing rules are never applied to an MA plan.","category":"plan_benefit","payerScope":"Medicare Advantage","planScope":"All MA plans","coverageTypes":["medicare_advantage"],"settings":"any","effectiveDate":"2006-01-01","jurisdiction":"US-Federal","source":"42 CFR Part 422; plan Evidence of Coverage","verificationStatus":"reference_cited","requiredInputs":["benefits.*"],"logicSummary":"Route MA through the plan-benefit path using only verified plan benefits.","logicKey":"ma_plan_specific","priority":30,"conflictBehavior":"advisory","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('PLAN-BEN-001', 1, 'plan_benefit', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"PLAN-BEN-001","name":"Benefits must be verified for this specific service","description":"Active coverage is not the same as a benefit. A copay, deductible, or coinsurance may be used only when verified for this service and setting with a recorded source.","category":"plan_benefit","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Ledgr design principle; payer eligibility & benefit (271) response or portal verification","verificationStatus":"reference_cited","requiredInputs":["benefits.benefitsVerified","benefits.benefitsSource"],"logicSummary":"Benefits not verified → ''Unable to determine a reliable amount — verification required''.","logicKey":"benefits_verified","priority":40,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('PLAN-BEN-002', 1, 'plan_benefit', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"PLAN-BEN-002","name":"ED visits use the emergency benefit, not the office copay","description":"An office-visit or specialist copay is never applied to an emergency department visit. Only a copay verified for the emergency setting may be used.","category":"plan_benefit","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":["emergency"],"effectiveDate":"2026-01-01","jurisdiction":"All","source":"Plan summary of benefits & coverage (SBC) — emergency room care line","verificationStatus":"reference_cited","requiredInputs":["benefits.copaySetting"],"logicSummary":"ED visit + copay setting ≠ emergency → verification required.","logicKey":"copay_setting_match","priority":41,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FAC-FAP-001', 1, 'facility_policy', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"FAC-FAP-001","name":"Financial assistance protects the patient from point-of-service collection","description":"Patients with an approved financial-assistance determination are not asked for point-of-service payments beyond what the policy allows; pending applications defer collection.","category":"facility_policy","payerScope":"All payers, self-pay","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"Facility","source":"Facility Financial Assistance Policy; for nonprofit hospitals see IRC § 501(r), 26 CFR §§ 1.501(r)-4 to -6","verificationStatus":"reference_cited","requiredInputs":["visit.financialAssistance"],"logicSummary":"Verified → no collection. Pending → defer collection, note account.","logicKey":"financial_assistance","priority":6,"conflictBehavior":"blocking","reviewer":"Patient Financial Services / Financial Counseling","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FAC-ED-001', 1, 'facility_policy', 'reference_cited', true, '{"enabled":true,"params":[{"key":"allowPostStabilizationCollection","label":"Allow verified ED copay collection after stabilization","type":"boolean","value":true}],"verificationDate":null,"id":"FAC-ED-001","name":"ED point-of-service collection after stabilization","description":"Whether staff may ask for a verified ED copay once the patient has been screened and stabilized (or at discharge).","category":"facility_policy","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":["emergency"],"effectiveDate":"2026-01-01","jurisdiction":"Facility","source":"Facility ED Patient Access policy","verificationStatus":"reference_cited","requiredInputs":["visit.edPhase"],"logicSummary":"If disabled, ED encounters after stabilization return ''No collection recommended at this stage''.","logicKey":"ed_post_stabilization","priority":7,"conflictBehavior":"blocking","reviewer":"ED Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FAC-EST-001', 1, 'facility_policy', 'reference_cited', true, '{"enabled":true,"params":[{"key":"allowEstimateCollection","label":"Allow collecting estimated amounts","type":"boolean","value":false}],"verificationDate":null,"id":"FAC-EST-001","name":"Estimate collection policy","description":"Whether staff may request payment of an estimated (not adjudicated) patient responsibility.","category":"facility_policy","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"Facility","source":"Facility Point-of-Service Collection policy","verificationStatus":"reference_cited","requiredInputs":[],"logicSummary":"If disabled, estimates are displayed for counseling only and the action is to wait for adjudication.","logicKey":"estimate_policy","priority":50,"conflictBehavior":"blocking","reviewer":"Revenue Cycle leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FAC-SEC-001', 1, 'facility_policy', 'reference_cited', true, '{"enabled":true,"params":[{"key":"collectPrimaryCopayWhenSecondaryExists","label":"Collect primary copay when downstream plans verified not to cover it","type":"boolean","value":false}],"verificationDate":null,"id":"FAC-SEC-001","name":"Primary copay when secondary coverage exists","description":"When a patient has secondary coverage, the secondary plan may cover the primary plan''s copay. By default Ledgr waits for adjudication rather than collecting the primary copay.","category":"facility_policy","payerScope":"All payers","planScope":"Dual and triple coverage","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"Facility","source":"Facility Point-of-Service Collection policy","verificationStatus":"reference_cited","requiredInputs":["plans[].benefits.coversPriorCostShare"],"logicSummary":"Disabled (default) → wait for adjudication. Enabled → collect the primary''s verified copay only when every downstream plan is verified NOT to cover prior cost-sharing.","logicKey":"secondary_copay_policy","priority":51,"conflictBehavior":"blocking","reviewer":"Revenue Cycle leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('FAC-REVIEW-001', 1, 'facility_policy', 'reference_cited', true, '{"enabled":true,"params":[{"key":"thresholdCents","label":"Review threshold","type":"cents","value":50000}],"verificationDate":null,"id":"FAC-REVIEW-001","name":"Supervisor review threshold","description":"Recommended collections above this amount require supervisor review before the registrar asks the patient.","category":"facility_policy","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"Facility","source":"Facility Point-of-Service Collection policy","verificationStatus":"reference_cited","requiredInputs":[],"logicSummary":"Amount > threshold → supervisorReview = true.","logicKey":"review_threshold","priority":90,"conflictBehavior":"advisory","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-ELIG-001', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-ELIG-001","name":"Coverage must be active and verified for the date of service","description":"Plans that are inactive, terminated, not yet effective, or unverified for the date of service are not used to compute any amount.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Eligibility (270/271) response or payer portal, with timestamp","verificationStatus":"reference_cited","requiredInputs":["plans[].eligibility","plans[].effectiveDate","plans[].terminationDate","visit.dateOfService"],"logicSummary":"Exclude inactive/out-of-window plans (warning). Any unverified plan → verification required. No usable plans → verification required / financial counseling.","logicKey":"eligibility","priority":3,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-ELIG-002', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-ELIG-002","name":"Retroactive or pending eligibility holds collection","description":"When eligibility is pending or may be applied retroactively (e.g., a Medicaid application), do not collect; route to financial counseling.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Facility eligibility-screening procedure","verificationStatus":"reference_cited","requiredInputs":["plans[].eligibility"],"logicSummary":"Any plan retro_pending → no collection, refer financial counseling.","logicKey":"retro_eligibility","priority":4,"conflictBehavior":"blocking","reviewer":"Financial Counseling","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-CONFLICT-001', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-CONFLICT-001","name":"Conflicting information requires review","description":"When sources disagree (eligibility vs. benefits, card vs. portal, COB conflict), Ledgr does not choose between them.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Ledgr design principle","verificationStatus":"reference_cited","requiredInputs":["plans[].conflictingInformation","plans[].cobStatus"],"logicSummary":"Any recorded conflict or COB status ''conflict'' → supervisor review.","logicKey":"conflicts","priority":5,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-SELFPAY-001', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-SELFPAY-001","name":"No coverage on file","description":"Self-pay and uninsured patients are screened for coverage and financial assistance before any collection.","category":"operational","payerScope":"Self-pay","planScope":"None","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Facility Financial Assistance Policy / self-pay procedure","verificationStatus":"reference_cited","requiredInputs":["plans"],"logicSummary":"No plans → refer to financial counseling; no copay concept applies.","logicKey":"self_pay","priority":3,"conflictBehavior":"blocking","reviewer":"Financial Counseling","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-WC-001', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-WC-001","name":"Workers'' compensation / auto liability: no copay at registration","description":"Work-related and accident-related encounters are billed to the carrier. Verify claim number and adjuster; do not collect a health-plan copay. These carriers are primary to Medicare when liable.","category":"operational","payerScope":"Workers'' comp, auto/no-fault, liability","planScope":"All","coverageTypes":["workers_comp","auto_liability"],"settings":"any","effectiveDate":"2026-01-01","jurisdiction":"State-specific (verify)","source":"State workers'' compensation statute (jurisdiction-specific); 42 U.S.C. § 1395y(b)(2) for Medicare interaction","verificationStatus":"reference_cited","requiredInputs":["plans[].type"],"logicSummary":"Any active WC/auto-liability plan → no collection, billing review.","logicKey":"wc_liability","priority":8,"conflictBehavior":"blocking","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-COB-001', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-COB-001","name":"Payer order must be confirmed and consistent","description":"With two or more plans, each plan needs a confirmed, unique payer position (1, 2, 3) and established COB. Card order, patient preference, or the higher copay never sets the order.","category":"operational","payerScope":"All payers","planScope":"Dual and triple coverage","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Payer COB response; NAIC Coordination of Benefits Model Regulation (MDL-120)","sourceUrl":"https://content.naic.org/sites/default/files/model-law-120.pdf","verificationStatus":"reference_cited","requiredInputs":["plans[].payerOrder","plans[].payerOrderConfirmed","plans[].cobStatus"],"logicSummary":"Dual: unconfirmed/invalid order or COB not established → verification required. Triple: unresolved → supervisor review.","logicKey":"payer_order","priority":15,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-COB-002', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-COB-002","name":"Dependent child with two parents'' plans (birthday rule)","description":"Many plans follow the NAIC ''birthday rule'' (the parent whose birthday falls earlier in the year is primary), but custody orders and plan terms can override it. Ledgr explains the rule; it does not set the order.","category":"operational","payerScope":"Commercial","planScope":"Dependent coverage","coverageTypes":["commercial_employer","commercial_individual","marketplace"],"settings":"any","effectiveDate":"2026-01-01","jurisdiction":"State-adopted NAIC model (varies)","source":"NAIC Coordination of Benefits Model Regulation (MDL-120), order of benefit determination rules","sourceUrl":"https://content.naic.org/sites/default/files/model-law-120.pdf","verificationStatus":"reference_cited","requiredInputs":["plans[].patientIsDependent","plans[].payerOrderConfirmed"],"logicSummary":"Two dependent plans with order unconfirmed → verification required, with birthday-rule guidance.","logicKey":"dependent_birthday","priority":16,"conflictBehavior":"advisory","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-NET-001', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-NET-001","name":"Network status must be known for network-based plans","description":"Commercial, marketplace, Medicare Advantage, Medicaid managed care, and TRICARE benefits depend on network status.","category":"operational","payerScope":"Network-based plans","planScope":"All","coverageTypes":["commercial_employer","commercial_individual","marketplace","medicare_advantage","medicaid_managed_care","tricare"],"settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Payer provider directory / contract status","verificationStatus":"reference_cited","requiredInputs":["visit.networkStatus"],"logicSummary":"Unknown → verification required. Out-of-network (non-ED) → supervisor review & financial counseling.","logicKey":"network","priority":17,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-AUTH-001', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-AUTH-001","name":"Authorization / referral required","description":"When the plan requires authorization or a referral that is not on file, flag it before the service.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Payer authorization requirements","verificationStatus":"reference_cited","requiredInputs":["benefits.authRequired","benefits.authOnFile"],"logicSummary":"Auth required and not on file → warning and next step (does not change the amount).","logicKey":"authorization","priority":42,"conflictBehavior":"advisory","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-CALC-001', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-CALC-001","name":"No copay stacking","description":"Copays from multiple plans are never added together, and the higher copay is never collected just because it is higher.","category":"operational","payerScope":"All payers","planScope":"Dual and triple coverage","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Ledgr calculation safeguard","verificationStatus":"reference_cited","requiredInputs":[],"logicSummary":"Only one plan''s verified cost-sharing (the primary''s) can ever be considered pre-adjudication.","logicKey":"no_stacking","priority":60,"conflictBehavior":"blocking","reviewer":"Revenue Cycle leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-CALC-002', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-CALC-002","name":"Credit amounts already collected","description":"Amounts already collected for this encounter are subtracted before any new request; overpayments go to billing review, never re-collected.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Ledgr calculation safeguard","verificationStatus":"reference_cited","requiredInputs":["visit.previouslyCollectedCents"],"logicSummary":"Amount due = max(0, amount − previously collected). Previously collected > final responsibility → billing review for credit balance.","logicKey":"previously_collected","priority":61,"conflictBehavior":"blocking","reviewer":"Revenue Cycle leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb),
('OPS-ADJ-001', 1, 'operational', 'reference_cited', true, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-ADJ-001","name":"Adjudicated balance comes from the last payer''s EOB/ERA","description":"After adjudication, the patient balance is the patient responsibility reported by the last payer in the sequence — never billed charges minus payments.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"835 ERA / EOB claim adjustment reason codes (patient responsibility group)","verificationStatus":"reference_cited","requiredInputs":["plans[].adjudication"],"logicSummary":"All payers adjudicated with EOBs → verified balance = last payer''s patient responsibility. Downstream payer not adjudicated → awaiting adjudication.","logicKey":"adjudicated_balance","priority":25,"conflictBehavior":"blocking","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb)
insert into public.rule_versions (rule_id, version, definition, summary) values
('FED-EMTALA-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-EMTALA-001","name":"EMTALA: no payment-related delay of screening or stabilization","description":"A hospital may not delay a medical screening examination or necessary stabilizing treatment to inquire about payment method or insurance status. Registration may proceed only in a way that does not delay screening or treatment.","category":"federal_law","payerScope":"All payers, including self-pay","planScope":"All","coverageTypes":"any","settings":["emergency"],"effectiveDate":"1986-04-07","jurisdiction":"US-Federal","source":"42 U.S.C. § 1395dd; 42 CFR § 489.24(d)(4)","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-G/part-489/subpart-B/section-489.24","verificationStatus":"reference_cited","requiredInputs":["visit.setting","visit.edPhase"],"logicSummary":"If the visit is an ED visit and the patient has not completed screening and any needed stabilization, stop: return ED workflow, no collection, no financial-prerequisite language. Unknown phase is treated as pre-screening.","logicKey":"ed_emtala_gate","priority":1,"conflictBehavior":"blocking","reviewer":"Compliance / ED Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-MSP-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MSP-001","name":"MSP: working aged — employer group plan primary (20+ employees)","description":"For a beneficiary entitled to Medicare by age who has group health plan coverage through their own or a spouse''s current employment with an employer of 20 or more employees, the group health plan pays first and Medicare is secondary.","category":"federal_law","payerScope":"Original Medicare","planScope":"Employer group health plan + Medicare","coverageTypes":["medicare_original","commercial_employer"],"settings":"any","effectiveDate":"1983-01-01","jurisdiction":"US-Federal","source":"42 U.S.C. § 1395y(b)(1)(A); 42 CFR Part 411 Subpart E (§ 411.172); CMS Pub. 100-05 (MSP Manual) Ch. 1–2","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-B/part-411/subpart-E","verificationStatus":"reference_cited","requiredInputs":["msp.entitlementBasis","msp.currentEmployment","msp.employerSize"],"logicSummary":"Age basis + current-employment GHP + employer size ≥ 20 → GHP primary. Age basis + no current employment (e.g., retiree plan) → Medicare primary. Any unknown → supervisor review.","logicKey":"msp_order","priority":10,"conflictBehavior":"blocking","reviewer":"Compliance / MSP coordinator","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-MSP-002', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MSP-002","name":"MSP: disability — large group health plan primary (100+ employees)","description":"For a beneficiary under 65 entitled to Medicare by disability who has large group health plan coverage based on current employment (employer of 100 or more employees), the large group health plan pays first.","category":"federal_law","payerScope":"Original Medicare","planScope":"Large group health plan + Medicare","coverageTypes":["medicare_original","commercial_employer"],"settings":"any","effectiveDate":"1987-01-01","jurisdiction":"US-Federal","source":"42 U.S.C. § 1395y(b)(1)(B); 42 CFR Part 411 Subpart H; CMS Pub. 100-05 Ch. 1–2","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-B/part-411/subpart-H","verificationStatus":"reference_cited","requiredInputs":["msp.entitlementBasis","msp.currentEmployment","msp.employerSize"],"logicSummary":"Disability basis + current-employment LGHP + employer size ≥ 100 → LGHP primary; otherwise Medicare primary; unknowns → review.","logicKey":"msp_order","priority":10,"conflictBehavior":"blocking","reviewer":"Compliance / MSP coordinator","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-MSP-003', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MSP-003","name":"MSP: ESRD 30-month coordination period","description":"For a beneficiary entitled to Medicare based on ESRD, a group health plan pays first during the 30-month coordination period, regardless of employer size or employment status.","category":"federal_law","payerScope":"Original Medicare","planScope":"Group health plan + Medicare (ESRD)","coverageTypes":["medicare_original","commercial_employer"],"settings":"any","effectiveDate":"1997-08-05","jurisdiction":"US-Federal","source":"42 U.S.C. § 1395y(b)(1)(C); 42 CFR § 411.162; CMS Pub. 100-05 Ch. 2","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-B/part-411/subpart-F","verificationStatus":"reference_cited","requiredInputs":["msp.entitlementBasis","msp.esrdInCoordinationPeriod"],"logicSummary":"ESRD basis + inside coordination period → GHP primary; after the period → Medicare primary; unknown → review.","logicKey":"msp_order","priority":10,"conflictBehavior":"blocking","reviewer":"Compliance / MSP coordinator","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-MSP-004', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MSP-004","name":"MSP: hospital must determine payer order before billing Medicare","description":"Hospitals must determine whether Medicare is primary for each inpatient and outpatient encounter (commonly via the MSP questionnaire). Card order, patient preference, or the higher copay never sets payer order.","category":"federal_law","payerScope":"Original Medicare","planScope":"Medicare with any other coverage","coverageTypes":["medicare_original"],"settings":"any","effectiveDate":"1983-01-01","jurisdiction":"US-Federal","source":"42 CFR § 489.20(g); CMS Pub. 100-05 (MSP Manual) Ch. 3 § 20","sourceUrl":"https://www.cms.gov/regulations-and-guidance/guidance/manuals/internet-only-manuals-ioms-items/cms019017","verificationStatus":"reference_cited","requiredInputs":["msp.questionnaireCompleted"],"logicSummary":"Original Medicare + another non-supplement, non-Medicaid plan + MSP questionnaire not completed → verification required.","logicKey":"msp_questionnaire","priority":9,"conflictBehavior":"blocking","reviewer":"Compliance / MSP coordinator","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-MCD-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MCD-001","name":"Medicaid is payer of last resort","description":"Medicaid generally pays only after all other liable third parties, including Medicare and commercial coverage. A Medicaid plan ordered ahead of other active coverage is a coordination conflict.","category":"federal_law","payerScope":"Medicaid / Medicaid managed care","planScope":"Medicaid with any other coverage","coverageTypes":["medicaid","medicaid_managed_care"],"settings":"any","effectiveDate":"1965-07-30","jurisdiction":"US-Federal","source":"42 U.S.C. § 1396a(a)(25); 42 CFR § 433.139","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-C/part-433/subpart-D/section-433.139","verificationStatus":"reference_cited","requiredInputs":["plans[].type","plans[].payerOrder"],"logicSummary":"If Medicaid is not last among active plans → supervisor review (coordination conflict). If Medicaid is secondary/tertiary → do not collect at registration; wait for adjudication.","logicKey":"medicaid_last_resort","priority":11,"conflictBehavior":"blocking","reviewer":"Compliance / Medicaid billing","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-MCD-002', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MCD-002","name":"QMB: no billing of Medicare cost-sharing","description":"Providers may not bill Qualified Medicare Beneficiaries for Medicare deductibles, coinsurance, or copayments, regardless of whether Medicaid pays.","category":"federal_law","payerScope":"Medicare + Medicaid (QMB)","planScope":"Dual-eligible, QMB","coverageTypes":["medicare_original","medicare_advantage","medicaid","medicaid_managed_care"],"settings":"any","effectiveDate":"1997-08-05","jurisdiction":"US-Federal","source":"42 U.S.C. § 1396a(n)(3)(B); 42 U.S.C. § 1395cc(a)(1)(A); CMS MLN Booklet ''Prohibition on Billing Dually Eligible Individuals Enrolled in the QMB Program''","sourceUrl":"https://www.cms.gov/outreach-and-education/medicare-learning-network-mln/mlnproducts/downloads/qmb.pdf","verificationStatus":"reference_cited","requiredInputs":["plans[].qmb"],"logicSummary":"Any active Medicaid plan flagged QMB → no collection of Medicare cost-sharing. Terminal.","logicKey":"qmb_protection","priority":5,"conflictBehavior":"blocking","reviewer":"Compliance","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-MCD-003', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MCD-003","name":"Medicaid cost-sharing limits and exemptions","description":"Federal rules cap Medicaid cost-sharing and exempt certain groups and services (for example, many children, pregnancy-related services, emergency services). Actual amounts are set by each state and must come from a verified state rule.","category":"federal_law","payerScope":"Medicaid / Medicaid managed care","planScope":"Medicaid as sole or primary payer","coverageTypes":["medicaid","medicaid_managed_care"],"settings":"any","effectiveDate":"2013-07-15","jurisdiction":"US-Federal","source":"42 CFR §§ 447.50–447.57","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-C/part-447/subpart-A","verificationStatus":"reference_cited","requiredInputs":["plans[].costSharingExempt","state Medicaid cost-sharing rule"],"logicSummary":"Exempt → no collection. Exemption unknown → verify. Not exempt → collect only a verified copay AND only if the state cost-sharing rule for the jurisdiction is marked verified; otherwise verification required.","logicKey":"medicaid_cost_sharing","priority":12,"conflictBehavior":"blocking","reviewer":"Compliance / Medicaid billing","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-NSA-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-NSA-001","name":"No Surprises Act: out-of-network emergency cost-sharing","description":"For emergency services from an out-of-network facility, group and individual health plans must apply in-network cost-sharing and the patient may not be balance billed. Out-of-network ED cost-sharing must be reviewed rather than collected at the desk.","category":"federal_law","payerScope":"Group & individual health plans","planScope":"Commercial, marketplace","coverageTypes":["commercial_employer","commercial_individual","marketplace"],"settings":["emergency"],"effectiveDate":"2022-01-01","jurisdiction":"US-Federal","source":"42 U.S.C. § 300gg-111; 45 CFR § 149.110","sourceUrl":"https://www.ecfr.gov/current/title-45/subtitle-A/subchapter-B/part-149/subpart-B/section-149.110","verificationStatus":"reference_cited","requiredInputs":["visit.networkStatus","visit.setting"],"logicSummary":"ED + out-of-network + commercial/marketplace plan → no desk collection; refer for billing review.","logicKey":"nsa_oon_emergency","priority":13,"conflictBehavior":"blocking","reviewer":"Compliance / Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-MEDIGAP-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MEDIGAP-001","name":"Medigap supplements Original Medicare only","description":"A Medicare Supplement (Medigap) policy pays after Original Medicare. It does not pay Medicare Advantage cost-sharing and cannot be primary.","category":"federal_law","payerScope":"Medigap","planScope":"Standardized Medigap plans","coverageTypes":["medigap"],"settings":"any","effectiveDate":"1992-07-30","jurisdiction":"US-Federal","source":"Social Security Act § 1882 (42 U.S.C. § 1395ss); CMS ''Choosing a Medigap Policy'' (Pub. 02110)","sourceUrl":"https://www.medicare.gov/publications/02110-medigap-guide-health-insurance.pdf","verificationStatus":"reference_cited","requiredInputs":["plans[].type","plans[].payerOrder"],"logicSummary":"Medigap without active Original Medicare, Medigap with Medicare Advantage, or Medigap ordered first → supervisor review.","logicKey":"medigap_structure","priority":11,"conflictBehavior":"blocking","reviewer":"Compliance","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-MEDICARE-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-MEDICARE-001","name":"Original Medicare cost-sharing is deductible + coinsurance on the approved amount","description":"Original Medicare cost-sharing generally consists of the Part A or Part B deductible plus coinsurance calculated on the Medicare-approved amount, not a fixed office-visit copay. Current-year amounts must be entered from a verified source.","category":"federal_law","payerScope":"Original Medicare","planScope":"Parts A & B","coverageTypes":["medicare_original"],"settings":"any","effectiveDate":"1966-07-01","jurisdiction":"US-Federal","source":"42 CFR §§ 409.82–409.83 (Part A), 410.152 and 410.160 (Part B)","sourceUrl":"https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-B/part-410/subpart-E","verificationStatus":"reference_cited","requiredInputs":["benefits.deductibleRemainingCents","benefits.coinsuranceBp","visit.allowedAmountEstimateCents"],"logicSummary":"Never treat Medicare as a fixed-copay plan. Produce an estimate only from verified remaining deductible + coinsurance + facility allowed-amount estimate, and only when the facility estimate policy allows.","logicKey":"medicare_original_cost_sharing","priority":20,"conflictBehavior":"blocking","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FED-TRICARE-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FED-TRICARE-001","name":"TRICARE generally pays after other health insurance","description":"TRICARE is generally secondary to other health insurance, with statutory exceptions (e.g., Medicaid and certain TRICARE supplements). TRICARE ordered ahead of other health insurance needs review.","category":"federal_law","payerScope":"TRICARE","planScope":"All TRICARE programs","coverageTypes":["tricare"],"settings":"any","effectiveDate":"1986-01-01","jurisdiction":"US-Federal","source":"10 U.S.C. § 1079(j); 32 CFR § 199.8","sourceUrl":"https://www.ecfr.gov/current/title-32/subtitle-A/chapter-I/subchapter-M/part-199/section-199.8","verificationStatus":"reference_cited","requiredInputs":["plans[].type","plans[].payerOrder"],"logicSummary":"TRICARE ordered before an active commercial/employer plan → supervisor review.","logicKey":"tricare_order","priority":11,"conflictBehavior":"blocking","reviewer":"Compliance","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('STATE-NC-MCD-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"STATE-NC-MCD-001","name":"NC Medicaid cost-sharing schedule","description":"Placeholder for North Carolina Medicaid copay amounts, exemptions, and point-of-service collection rules. Must be completed from current NC DHHS / NC Medicaid guidance before Ledgr may recommend any Medicaid copay for NC encounters.","category":"state_law","payerScope":"NC Medicaid (FFS and Prepaid Health Plans)","planScope":"NC Medicaid","coverageTypes":["medicaid","medicaid_managed_care"],"settings":"any","effectiveDate":"2026-01-01","jurisdiction":"NC","source":"NC Medicaid clinical/billing policy — TO BE SUPPLIED by compliance","verificationStatus":"draft","requiredInputs":["visit.jurisdiction"],"logicSummary":"While this rule is draft, no Medicaid copay may be recommended for NC; returns verification required.","logicKey":"state_medicaid_schedule","priority":12,"conflictBehavior":"blocking","reviewer":"Compliance (NC)","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('PLAN-MEDIGAP-G', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"PLAN-MEDIGAP-G","name":"Medigap Plan G benefit structure","description":"Plan G covers Medicare Part A and Part B cost-sharing covered by the standardized plan, including the Part A deductible and Part B coinsurance, but generally does NOT cover the Part B deductible.","category":"plan_benefit","payerScope":"Medigap","planScope":"Standardized Plan G","coverageTypes":["medigap"],"settings":"any","effectiveDate":"2010-06-01","jurisdiction":"US-Federal (standardized)","source":"CMS ''Choosing a Medigap Policy'' (Pub. 02110), Medigap plan chart","sourceUrl":"https://www.medicare.gov/publications/02110-medigap-guide-health-insurance.pdf","verificationStatus":"reference_cited","requiredInputs":["plans[].medigapLetter","medicare.benefits.deductibleRemainingCents"],"logicSummary":"Original Medicare + active Plan G: no standard copay. Inpatient → no facility collection. Outpatient: Part B deductible verified met → no collection; deductible remaining → at most the remaining Part B deductible, as an estimate only and only if the facility allows estimates; unknown → verification required.","logicKey":"medigap_g","priority":30,"conflictBehavior":"blocking","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('PLAN-MEDIGAP-OTHER', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"PLAN-MEDIGAP-OTHER","name":"Other Medigap letters require plan-specific benefit verification","description":"Medigap letters differ (some cover the Part B deductible on older policies; some have copays). Ledgr does not assume benefits for letters other than G.","category":"plan_benefit","payerScope":"Medigap","planScope":"Plans A, B, C, D, F, K, L, M, N (and high-deductible variants)","coverageTypes":["medigap"],"settings":"any","effectiveDate":"2010-06-01","jurisdiction":"US-Federal (standardized)","source":"CMS ''Choosing a Medigap Policy'' (Pub. 02110)","verificationStatus":"reference_cited","requiredInputs":["plans[].medigapLetter"],"logicSummary":"Medigap letter other than G, or missing letter → verification required.","logicKey":"medigap_other","priority":30,"conflictBehavior":"blocking","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('PLAN-MA-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"PLAN-MA-001","name":"Medicare Advantage uses plan-specific benefits","description":"Medicare Advantage plans set their own copays, coinsurance, networks, and authorization rules. Original Medicare cost-sharing rules are never applied to an MA plan.","category":"plan_benefit","payerScope":"Medicare Advantage","planScope":"All MA plans","coverageTypes":["medicare_advantage"],"settings":"any","effectiveDate":"2006-01-01","jurisdiction":"US-Federal","source":"42 CFR Part 422; plan Evidence of Coverage","verificationStatus":"reference_cited","requiredInputs":["benefits.*"],"logicSummary":"Route MA through the plan-benefit path using only verified plan benefits.","logicKey":"ma_plan_specific","priority":30,"conflictBehavior":"advisory","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('PLAN-BEN-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"PLAN-BEN-001","name":"Benefits must be verified for this specific service","description":"Active coverage is not the same as a benefit. A copay, deductible, or coinsurance may be used only when verified for this service and setting with a recorded source.","category":"plan_benefit","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Ledgr design principle; payer eligibility & benefit (271) response or portal verification","verificationStatus":"reference_cited","requiredInputs":["benefits.benefitsVerified","benefits.benefitsSource"],"logicSummary":"Benefits not verified → ''Unable to determine a reliable amount — verification required''.","logicKey":"benefits_verified","priority":40,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('PLAN-BEN-002', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"PLAN-BEN-002","name":"ED visits use the emergency benefit, not the office copay","description":"An office-visit or specialist copay is never applied to an emergency department visit. Only a copay verified for the emergency setting may be used.","category":"plan_benefit","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":["emergency"],"effectiveDate":"2026-01-01","jurisdiction":"All","source":"Plan summary of benefits & coverage (SBC) — emergency room care line","verificationStatus":"reference_cited","requiredInputs":["benefits.copaySetting"],"logicSummary":"ED visit + copay setting ≠ emergency → verification required.","logicKey":"copay_setting_match","priority":41,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FAC-FAP-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"FAC-FAP-001","name":"Financial assistance protects the patient from point-of-service collection","description":"Patients with an approved financial-assistance determination are not asked for point-of-service payments beyond what the policy allows; pending applications defer collection.","category":"facility_policy","payerScope":"All payers, self-pay","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"Facility","source":"Facility Financial Assistance Policy; for nonprofit hospitals see IRC § 501(r), 26 CFR §§ 1.501(r)-4 to -6","verificationStatus":"reference_cited","requiredInputs":["visit.financialAssistance"],"logicSummary":"Verified → no collection. Pending → defer collection, note account.","logicKey":"financial_assistance","priority":6,"conflictBehavior":"blocking","reviewer":"Patient Financial Services / Financial Counseling","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FAC-ED-001', 1, '{"enabled":true,"params":[{"key":"allowPostStabilizationCollection","label":"Allow verified ED copay collection after stabilization","type":"boolean","value":true}],"verificationDate":null,"id":"FAC-ED-001","name":"ED point-of-service collection after stabilization","description":"Whether staff may ask for a verified ED copay once the patient has been screened and stabilized (or at discharge).","category":"facility_policy","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":["emergency"],"effectiveDate":"2026-01-01","jurisdiction":"Facility","source":"Facility ED Patient Access policy","verificationStatus":"reference_cited","requiredInputs":["visit.edPhase"],"logicSummary":"If disabled, ED encounters after stabilization return ''No collection recommended at this stage''.","logicKey":"ed_post_stabilization","priority":7,"conflictBehavior":"blocking","reviewer":"ED Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FAC-EST-001', 1, '{"enabled":true,"params":[{"key":"allowEstimateCollection","label":"Allow collecting estimated amounts","type":"boolean","value":false}],"verificationDate":null,"id":"FAC-EST-001","name":"Estimate collection policy","description":"Whether staff may request payment of an estimated (not adjudicated) patient responsibility.","category":"facility_policy","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"Facility","source":"Facility Point-of-Service Collection policy","verificationStatus":"reference_cited","requiredInputs":[],"logicSummary":"If disabled, estimates are displayed for counseling only and the action is to wait for adjudication.","logicKey":"estimate_policy","priority":50,"conflictBehavior":"blocking","reviewer":"Revenue Cycle leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FAC-SEC-001', 1, '{"enabled":true,"params":[{"key":"collectPrimaryCopayWhenSecondaryExists","label":"Collect primary copay when downstream plans verified not to cover it","type":"boolean","value":false}],"verificationDate":null,"id":"FAC-SEC-001","name":"Primary copay when secondary coverage exists","description":"When a patient has secondary coverage, the secondary plan may cover the primary plan''s copay. By default Ledgr waits for adjudication rather than collecting the primary copay.","category":"facility_policy","payerScope":"All payers","planScope":"Dual and triple coverage","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"Facility","source":"Facility Point-of-Service Collection policy","verificationStatus":"reference_cited","requiredInputs":["plans[].benefits.coversPriorCostShare"],"logicSummary":"Disabled (default) → wait for adjudication. Enabled → collect the primary''s verified copay only when every downstream plan is verified NOT to cover prior cost-sharing.","logicKey":"secondary_copay_policy","priority":51,"conflictBehavior":"blocking","reviewer":"Revenue Cycle leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('FAC-REVIEW-001', 1, '{"enabled":true,"params":[{"key":"thresholdCents","label":"Review threshold","type":"cents","value":50000}],"verificationDate":null,"id":"FAC-REVIEW-001","name":"Supervisor review threshold","description":"Recommended collections above this amount require supervisor review before the registrar asks the patient.","category":"facility_policy","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"Facility","source":"Facility Point-of-Service Collection policy","verificationStatus":"reference_cited","requiredInputs":[],"logicSummary":"Amount > threshold → supervisorReview = true.","logicKey":"review_threshold","priority":90,"conflictBehavior":"advisory","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-ELIG-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-ELIG-001","name":"Coverage must be active and verified for the date of service","description":"Plans that are inactive, terminated, not yet effective, or unverified for the date of service are not used to compute any amount.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Eligibility (270/271) response or payer portal, with timestamp","verificationStatus":"reference_cited","requiredInputs":["plans[].eligibility","plans[].effectiveDate","plans[].terminationDate","visit.dateOfService"],"logicSummary":"Exclude inactive/out-of-window plans (warning). Any unverified plan → verification required. No usable plans → verification required / financial counseling.","logicKey":"eligibility","priority":3,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-ELIG-002', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-ELIG-002","name":"Retroactive or pending eligibility holds collection","description":"When eligibility is pending or may be applied retroactively (e.g., a Medicaid application), do not collect; route to financial counseling.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Facility eligibility-screening procedure","verificationStatus":"reference_cited","requiredInputs":["plans[].eligibility"],"logicSummary":"Any plan retro_pending → no collection, refer financial counseling.","logicKey":"retro_eligibility","priority":4,"conflictBehavior":"blocking","reviewer":"Financial Counseling","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-CONFLICT-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-CONFLICT-001","name":"Conflicting information requires review","description":"When sources disagree (eligibility vs. benefits, card vs. portal, COB conflict), Ledgr does not choose between them.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Ledgr design principle","verificationStatus":"reference_cited","requiredInputs":["plans[].conflictingInformation","plans[].cobStatus"],"logicSummary":"Any recorded conflict or COB status ''conflict'' → supervisor review.","logicKey":"conflicts","priority":5,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-SELFPAY-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-SELFPAY-001","name":"No coverage on file","description":"Self-pay and uninsured patients are screened for coverage and financial assistance before any collection.","category":"operational","payerScope":"Self-pay","planScope":"None","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Facility Financial Assistance Policy / self-pay procedure","verificationStatus":"reference_cited","requiredInputs":["plans"],"logicSummary":"No plans → refer to financial counseling; no copay concept applies.","logicKey":"self_pay","priority":3,"conflictBehavior":"blocking","reviewer":"Financial Counseling","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-WC-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-WC-001","name":"Workers'' compensation / auto liability: no copay at registration","description":"Work-related and accident-related encounters are billed to the carrier. Verify claim number and adjuster; do not collect a health-plan copay. These carriers are primary to Medicare when liable.","category":"operational","payerScope":"Workers'' comp, auto/no-fault, liability","planScope":"All","coverageTypes":["workers_comp","auto_liability"],"settings":"any","effectiveDate":"2026-01-01","jurisdiction":"State-specific (verify)","source":"State workers'' compensation statute (jurisdiction-specific); 42 U.S.C. § 1395y(b)(2) for Medicare interaction","verificationStatus":"reference_cited","requiredInputs":["plans[].type"],"logicSummary":"Any active WC/auto-liability plan → no collection, billing review.","logicKey":"wc_liability","priority":8,"conflictBehavior":"blocking","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-COB-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-COB-001","name":"Payer order must be confirmed and consistent","description":"With two or more plans, each plan needs a confirmed, unique payer position (1, 2, 3) and established COB. Card order, patient preference, or the higher copay never sets the order.","category":"operational","payerScope":"All payers","planScope":"Dual and triple coverage","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Payer COB response; NAIC Coordination of Benefits Model Regulation (MDL-120)","sourceUrl":"https://content.naic.org/sites/default/files/model-law-120.pdf","verificationStatus":"reference_cited","requiredInputs":["plans[].payerOrder","plans[].payerOrderConfirmed","plans[].cobStatus"],"logicSummary":"Dual: unconfirmed/invalid order or COB not established → verification required. Triple: unresolved → supervisor review.","logicKey":"payer_order","priority":15,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-COB-002', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-COB-002","name":"Dependent child with two parents'' plans (birthday rule)","description":"Many plans follow the NAIC ''birthday rule'' (the parent whose birthday falls earlier in the year is primary), but custody orders and plan terms can override it. Ledgr explains the rule; it does not set the order.","category":"operational","payerScope":"Commercial","planScope":"Dependent coverage","coverageTypes":["commercial_employer","commercial_individual","marketplace"],"settings":"any","effectiveDate":"2026-01-01","jurisdiction":"State-adopted NAIC model (varies)","source":"NAIC Coordination of Benefits Model Regulation (MDL-120), order of benefit determination rules","sourceUrl":"https://content.naic.org/sites/default/files/model-law-120.pdf","verificationStatus":"reference_cited","requiredInputs":["plans[].patientIsDependent","plans[].payerOrderConfirmed"],"logicSummary":"Two dependent plans with order unconfirmed → verification required, with birthday-rule guidance.","logicKey":"dependent_birthday","priority":16,"conflictBehavior":"advisory","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-NET-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-NET-001","name":"Network status must be known for network-based plans","description":"Commercial, marketplace, Medicare Advantage, Medicaid managed care, and TRICARE benefits depend on network status.","category":"operational","payerScope":"Network-based plans","planScope":"All","coverageTypes":["commercial_employer","commercial_individual","marketplace","medicare_advantage","medicaid_managed_care","tricare"],"settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Payer provider directory / contract status","verificationStatus":"reference_cited","requiredInputs":["visit.networkStatus"],"logicSummary":"Unknown → verification required. Out-of-network (non-ED) → supervisor review & financial counseling.","logicKey":"network","priority":17,"conflictBehavior":"blocking","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-AUTH-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-AUTH-001","name":"Authorization / referral required","description":"When the plan requires authorization or a referral that is not on file, flag it before the service.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Payer authorization requirements","verificationStatus":"reference_cited","requiredInputs":["benefits.authRequired","benefits.authOnFile"],"logicSummary":"Auth required and not on file → warning and next step (does not change the amount).","logicKey":"authorization","priority":42,"conflictBehavior":"advisory","reviewer":"Patient Access leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-CALC-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-CALC-001","name":"No copay stacking","description":"Copays from multiple plans are never added together, and the higher copay is never collected just because it is higher.","category":"operational","payerScope":"All payers","planScope":"Dual and triple coverage","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Ledgr calculation safeguard","verificationStatus":"reference_cited","requiredInputs":[],"logicSummary":"Only one plan''s verified cost-sharing (the primary''s) can ever be considered pre-adjudication.","logicKey":"no_stacking","priority":60,"conflictBehavior":"blocking","reviewer":"Revenue Cycle leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-CALC-002', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-CALC-002","name":"Credit amounts already collected","description":"Amounts already collected for this encounter are subtracted before any new request; overpayments go to billing review, never re-collected.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"Ledgr calculation safeguard","verificationStatus":"reference_cited","requiredInputs":["visit.previouslyCollectedCents"],"logicSummary":"Amount due = max(0, amount − previously collected). Previously collected > final responsibility → billing review for credit balance.","logicKey":"previously_collected","priority":61,"conflictBehavior":"blocking","reviewer":"Revenue Cycle leadership","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.'),
('OPS-ADJ-001', 1, '{"enabled":true,"params":[],"verificationDate":null,"id":"OPS-ADJ-001","name":"Adjudicated balance comes from the last payer''s EOB/ERA","description":"After adjudication, the patient balance is the patient responsibility reported by the last payer in the sequence — never billed charges minus payments.","category":"operational","payerScope":"All payers","planScope":"All","coverageTypes":"any","settings":"any","effectiveDate":"2026-01-01","jurisdiction":"All","source":"835 ERA / EOB claim adjustment reason codes (patient responsibility group)","verificationStatus":"reference_cited","requiredInputs":["plans[].adjudication"],"logicSummary":"All payers adjudicated with EOBs → verified balance = last payer''s patient responsibility. Downstream payer not adjudicated → awaiting adjudication.","logicKey":"adjudicated_balance","priority":25,"conflictBehavior":"blocking","reviewer":"Patient Financial Services","version":1,"history":[{"version":1,"changedAt":"2026-10-19","changedBy":"Ledgr seed library","approvedBy":null,"summary":"Initial seed — awaiting compliance validation."}]}'::jsonb, 'Initial seed — awaiting compliance validation.')
